import ExcelJS from 'exceljs';
import { saveAs } from 'file-saver';

/**
 * Generates a styled, human-readable multi-sheet Excel file of the show configuration
 */
export async function exportShowWorkbook(project) {
  const workbook = new ExcelJS.Workbook();
  workbook.creator = 'Magic Smoke - Great Balls of Fire';
  workbook.lastModifiedBy = 'Magic Smoke';
  workbook.created = new Date();
  workbook.modified = new Date();

  // ----------------------------------------------------
  // SHEET 1: Script
  // ----------------------------------------------------
  const scriptSheet = workbook.addWorksheet('Script');
  scriptSheet.views = [{ showGridLines: true }];

  scriptSheet.columns = [
    { header: 'Event/Effect ID', key: 'event_id', width: 16 },
    { header: 'Time Offset (ms)', key: 'time_ms', width: 18 },
    { header: 'Time (s)', key: 'time_s', width: 12 },
    { header: 'Event/Effect Title', key: 'title', width: 45 },
    { header: 'Firework Name', key: 'firework_name', width: 32 },
    { header: 'Qty', key: 'quantity', width: 8 },
    { header: 'Field Mapped', key: 'field_mapped', width: 15 },
    { header: 'Pallet Location', key: 'location', width: 18 },
    { header: 'Relay Port', key: 'relay', width: 12 },
    { header: 'Modifications', key: 'mods', width: 22 },
    { header: 'Fuse Delay (ms)', key: 'fuse_delay', width: 16 },
    { header: 'Setup/Build Notes', key: 'notes', width: 35 }
  ];

  // Style Header Row
  const headerRow = scriptSheet.getRow(1);
  headerRow.height = 28;
  headerRow.eachCell((cell) => {
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF1F497D' } // Dark slate blue
    };
    cell.font = {
      name: 'Segoe UI',
      size: 11,
      bold: true,
      color: { argb: 'FFFFFFFF' }
    };
    cell.alignment = { vertical: 'middle', horizontal: 'center' };
  });

  // Populate events
  let rowIdx = 2;
  (project.events || []).forEach((evt, evtIndex) => {
    (evt.fireworks || []).forEach((fw) => {
      // Determine field mapping
      const fields = [];
      if (fw.fields?.left) fields.push('L');
      if (fw.fields?.center) fields.push('C');
      if (fw.fields?.right) fields.push('R');
      const fieldText = fields.join('+');

      // Modifications Text
      const modsList = [];
      if (fw.flashFuse) modsList.push('FLASH');
      if (fw.sliceSegment && fw.sliceSegment !== '1') modsList.push(`MOD ${fw.sliceSegment}`);
      const modsText = modsList.join(' & ');

      const rowData = {
        event_id: evt.event_num,
        time_ms: evt.timestamp_offset_ms,
        time_s: parseFloat((evt.timestamp_offset_ms / 1000).toFixed(2)),
        title: evt.title || '',
        firework_name: fw.name,
        quantity: fw.quantity,
        field_mapped: fieldText,
        location: fw.location || '',
        relay: fw.relay || '',
        mods: modsText,
        fuse_delay: evt.fuseDelay || 0,
        notes: evt.setupNotes || ''
      };

      const row = scriptSheet.addRow(rowData);
      row.height = 22;

      // Formatting cell by cell
      const isEven = evtIndex % 2 === 0;
      row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
        cell.font = { name: 'Segoe UI', size: 10 };
        cell.alignment = { vertical: 'middle' };

        // Alternating row zebra striping
        if (isEven) {
          cell.fill = {
            type: 'pattern',
            pattern: 'solid',
            fgColor: { argb: 'FFF2F2F2' } // Soft zebra gray
          };
        }

        // Apply borders
        cell.border = {
          top: { style: 'thin', color: { argb: 'FFE0E0E0' } },
          bottom: { style: 'thin', color: { argb: 'FFE0E0E0' } },
          left: { style: 'thin', color: { argb: 'FFE0E0E0' } },
          right: { style: 'thin', color: { argb: 'FFE0E0E0' } }
        };

        // Align numbers to center
        if ([1, 2, 3, 6, 7, 8, 9, 10, 11].includes(colNumber)) {
          cell.alignment = { vertical: 'middle', horizontal: 'center' };
        }
      });

      // Field Location Highlighting
      const locCell = row.getCell('location');
      const locVal = locCell.value ? locCell.value.toString().toUpperCase() : '';
      if (locVal.startsWith('L')) {
        locCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFD9E1F2' } }; // Soft blue
      } else if (locVal.startsWith('C')) {
        locCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE2EFDA' } }; // Soft green
      } else if (locVal.startsWith('R')) {
        locCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2D7D5' } }; // Soft purple
      }

      // FLASH highlights
      const modsCell = row.getCell('mods');
      if (modsCell.value && modsCell.value.toString().includes('FLASH')) {
        modsCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFCE4D6' } }; // Soft orange/red
        modsCell.font = { name: 'Segoe UI', size: 10, bold: true, color: { argb: 'FFC00000' } };
      }

      rowIdx++;
    });
  });

  // ----------------------------------------------------
  // SHEET 2: Song Tracks
  // ----------------------------------------------------
  const songSheet = workbook.addWorksheet('Song Tracks');
  songSheet.views = [{ showGridLines: true }];

  songSheet.columns = [
    { header: 'Song Number', key: 'song_num', width: 15 },
    { header: 'Start Time (ms)', key: 'start_time_ms', width: 18 },
    { header: 'Start Time (s)', key: 'start_time_s', width: 15 },
    { header: 'Song Title', key: 'title', width: 35 },
    { header: 'Artist', key: 'artist', width: 30 }
  ];

  const songHeaderRow = songSheet.getRow(1);
  songHeaderRow.height = 28;
  songHeaderRow.eachCell((cell) => {
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF366092' } // Alternate Slate Blue
    };
    cell.font = { name: 'Segoe UI', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cell.alignment = { vertical: 'middle', horizontal: 'center' };
  });

  (project.songTracks || []).forEach((song, idx) => {
    const row = songSheet.addRow({
      song_num: song.song_num,
      start_time_ms: song.start_time_ms,
      start_time_s: parseFloat((song.start_time_ms / 1000).toFixed(2)),
      title: song.title || '',
      artist: song.artist || ''
    });
    row.height = 22;
    row.eachCell((cell) => {
      cell.font = { name: 'Segoe UI', size: 10 };
      cell.alignment = { vertical: 'middle', horizontal: 'center' };
      cell.border = {
        top: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        bottom: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        left: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        right: { style: 'thin', color: { argb: 'FFE0E0E0' } }
      };
      if (idx % 2 === 0) {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F2F2' } };
      }
    });
    // Align title and artist to left
    row.getCell('title').alignment = { vertical: 'middle', horizontal: 'left' };
    row.getCell('artist').alignment = { vertical: 'middle', horizontal: 'left' };
  });

  // ----------------------------------------------------
  // SHEET 3: Locations
  // ----------------------------------------------------
  const locSheet = workbook.addWorksheet('Locations');
  locSheet.views = [{ showGridLines: true }];

  locSheet.columns = [
    { header: 'Location ID', key: 'location_id', width: 16 },
    { header: 'ESP32 Node Hostname', key: 'node_hostname', width: 25 },
    { header: 'MAC Address', key: 'mac_addr', width: 22 }
  ];

  const locHeaderRow = locSheet.getRow(1);
  locHeaderRow.height = 28;
  locHeaderRow.eachCell((cell) => {
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF595959' } // Dark gray header
    };
    cell.font = { name: 'Segoe UI', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cell.alignment = { vertical: 'middle', horizontal: 'center' };
  });

  (project.locations || []).forEach((loc, idx) => {
    const row = locSheet.addRow({
      location_id: loc.location_id,
      node_hostname: loc.node_hostname || '',
      mac_addr: loc.mac_addr || ''
    });
    row.height = 22;
    row.eachCell((cell) => {
      cell.font = { name: 'Segoe UI', size: 10 };
      cell.alignment = { vertical: 'middle', horizontal: 'center' };
      cell.border = {
        top: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        bottom: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        left: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        right: { style: 'thin', color: { argb: 'FFE0E0E0' } }
      };
      if (idx % 2 === 0) {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F2F2' } };
      }
    });
  });

  // Write and Save
  const buffer = await workbook.xlsx.writeBuffer();
  saveAs(new Blob([buffer]), `${project.name.replace(/\s+/g, '_')}_script.xlsx`);
}

/**
 * Exports a summarized wholesales order sheet with whole-integer ceiling rounded counts
 */
export async function exportInventoryOrderSheet(project) {
  const workbook = new ExcelJS.Workbook();
  const orderSheet = workbook.addWorksheet('Inventory Order Sheet');
  orderSheet.views = [{ showGridLines: true }];

  orderSheet.columns = [
    { header: 'Wholesale Firework Name', key: 'name', width: 35 },
    { header: 'Exact Plan Count (Fractional Sum)', key: 'fractional_count', width: 32 },
    { header: 'Required Order Quantity (Ceiling Round)', key: 'rounded_count', width: 35 }
  ];

  // Style Header Row
  const headerRow = orderSheet.getRow(1);
  headerRow.height = 28;
  headerRow.eachCell((cell) => {
    cell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FFC00000' } // Accent Red
    };
    cell.font = { name: 'Segoe UI', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
    cell.alignment = { vertical: 'middle', horizontal: 'center' };
  });

  // Collect distinct fireworks and count them including slice fractions
  const totals = {}; // { 'Firework Name': total_fractional_units }

  (project.events || []).forEach((evt) => {
    (evt.fireworks || []).forEach((fw) => {
      // Calculate multiplier from active fields
      let fieldCount = 0;
      if (fw.fields?.left) fieldCount++;
      if (fw.fields?.center) fieldCount++;
      if (fw.fields?.right) fieldCount++;

      // Slice fraction
      let sliceFraction = 1;
      if (fw.sliceSegment === '1/2') sliceFraction = 0.5;
      else if (fw.sliceSegment === '1/3') sliceFraction = 0.333333333;
      else if (fw.sliceSegment === '1/4') sliceFraction = 0.25;

      const delta = fw.quantity * fieldCount * sliceFraction;
      totals[fw.name] = (totals[fw.name] || 0) + delta;
    });
  });

  const names = Object.keys(totals).sort();
  names.forEach((name, idx) => {
    const rawVal = totals[name];
    const roundedVal = Math.ceil(rawVal); // Whole integer ceiling function

    const row = orderSheet.addRow({
      name: name,
      fractional_count: parseFloat(rawVal.toFixed(3)),
      rounded_count: roundedVal
    });
    row.height = 22;
    row.eachCell((cell) => {
      cell.font = { name: 'Segoe UI', size: 10 };
      cell.alignment = { vertical: 'middle' };
      cell.border = {
        top: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        bottom: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        left: { style: 'thin', color: { argb: 'FFE0E0E0' } },
        right: { style: 'thin', color: { argb: 'FFE0E0E0' } }
      };
      if (idx % 2 === 0) {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F2F2' } };
      }
    });

    row.getCell('fractional_count').alignment = { vertical: 'middle', horizontal: 'center' };
    row.getCell('rounded_count').alignment = { vertical: 'middle', horizontal: 'center' };
  });

  const buffer = await workbook.xlsx.writeBuffer();
  saveAs(new Blob([buffer]), `${project.name.replace(/\s+/g, '_')}_wholesaler_order.xlsx`);
}

/**
 * Imports a show workbook containing Script, Song Tracks, and Locations sheets
 * @param {File} file The uploaded Excel file object
 * @returns {Promise<Object>} Object containing parsed events, songTracks, and locations lists
 */
export async function importShowWorkbook(file) {
  const workbook = new ExcelJS.Workbook();
  const arrayBuffer = await file.arrayBuffer();
  await workbook.xlsx.load(arrayBuffer);
  
  let events = [];
  let songTracks = [];
  let locations = [];

  // 1. Parse Script Sheet
  const scriptSheet = workbook.getWorksheet('Script') || workbook.worksheets[0];
  if (scriptSheet) {
    const headerRow = scriptSheet.getRow(1);
    const headers = {};
    headerRow.eachCell((cell, colNumber) => {
      if (cell.value) {
        headers[cell.value.toString().toLowerCase().trim()] = colNumber;
      }
    });

    // Find column indices
    const colId = headers['event/effect id'] || headers['eventnum'] || headers['event id'] || headers['event_num'] || 1;
    const colMs = headers['time offset (ms)'] || headers['offsetms'] || headers['time_ms'] || headers['time offset'] || 2;
    const colS = headers['time (s)'] || headers['offsetsec'] || headers['time_s'] || 3;
    const colTitle = headers['event/effect title'] || headers['title'] || 4;
    const colFw = headers['firework name'] || headers['firework_name'] || 5;
    const colQty = headers['qty'] || headers['quantity'] || 6;
    const colLoc = headers['pallet location'] || headers['location'] || 8;
    const colRelay = headers['relay port'] || headers['relay'] || 9;
    const colFuse = headers['fuse delay (ms)'] || headers['fuse_delay'] || headers['fuse delay'] || 11;
    const colNotes = headers['setup/build notes'] || headers['notes'] || 12;

    const eventsMap = {};

    scriptSheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) return; // skip header
      
      const eventNum = row.getCell(colId).value?.toString().trim();
      if (!eventNum) return;

      let ms = parseInt(row.getCell(colMs).value);
      if (isNaN(ms)) {
        const s = parseFloat(row.getCell(colS).value);
        if (!isNaN(s)) ms = Math.round(s * 1000);
        else ms = 0;
      }

      const title = row.getCell(colTitle).value?.toString().trim() || '';
      const fwName = row.getCell(colFw).value?.toString().trim() || '';
      const qty = parseInt(row.getCell(colQty).value) || 1;
      const loc = row.getCell(colLoc).value?.toString().trim() || '';
      const relayVal = row.getCell(colRelay).value;
      const relayIdx = (relayVal !== undefined && relayVal !== null) ? parseInt(relayVal) : 0;
      const fuse = parseInt(row.getCell(colFuse).value) || 0;
      const notes = row.getCell(colNotes).value?.toString().trim() || '';

      if (!eventsMap[eventNum]) {
        eventsMap[eventNum] = {
          event_id: eventNum,
          event_num: eventNum,
          timestamp_offset_ms: ms,
          title: title,
          fuseDelay: fuse,
          setupNotes: notes,
          relays: []
        };
      }

      if (fwName) {
        // Add relay entry based on quantity
        for (let q = 0; q < qty; q++) {
          eventsMap[eventNum].relays.push({
            location_id: loc,
            relay_idx: relayIdx,
            duration_ms: 150,
            firework_name: fwName
          });
        }
      }
    });

    events = Object.values(eventsMap).sort((a, b) => a.timestamp_offset_ms - b.timestamp_offset_ms);
  }

  // 2. Parse Song Tracks Sheet
  const songSheet = workbook.getWorksheet('Song Tracks');
  if (songSheet) {
    const headerRow = songSheet.getRow(1);
    const headers = {};
    headerRow.eachCell((cell, colNumber) => {
      if (cell.value) {
        headers[cell.value.toString().toLowerCase().trim()] = colNumber;
      }
    });

    const colNum = headers['song number'] || headers['song_num'] || 1;
    const colMs = headers['start time (ms)'] || headers['start_time_ms'] || 2;
    const colS = headers['start time (s)'] || headers['start_time_s'] || 3;
    const colTitle = headers['song title'] || headers['title'] || 4;
    const colArtist = headers['artist'] || 5;

    songSheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) return;
      const num = parseInt(row.getCell(colNum).value);
      if (isNaN(num)) return;

      let ms = parseInt(row.getCell(colMs).value);
      if (isNaN(ms)) {
        const s = parseFloat(row.getCell(colS).value);
        if (!isNaN(s)) ms = Math.round(s * 1000);
        else ms = 0;
      }

      const title = row.getCell(colTitle).value?.toString().trim() || `Song #${num}`;
      const artist = row.getCell(colArtist).value?.toString().trim() || 'Unknown';

      songTracks.push({
        song_num: num,
        start_time_ms: ms,
        title,
        artist
      });
    });
    songTracks.sort((a, b) => a.start_time_ms - b.start_time_ms);
  }

  // 3. Parse Locations Sheet
  const locSheet = workbook.getWorksheet('Locations');
  if (locSheet) {
    const headerRow = locSheet.getRow(1);
    const headers = {};
    headerRow.eachCell((cell, colNumber) => {
      if (cell.value) {
        headers[cell.value.toString().toLowerCase().trim()] = colNumber;
      }
    });

    const colId = headers['location id'] || headers['location_id'] || 1;
    const colHost = headers['esp32 node hostname'] || headers['node_hostname'] || 2;
    const colMac = headers['mac address'] || headers['mac_addr'] || 3;

    locSheet.eachRow((row, rowNumber) => {
      if (rowNumber === 1) return;
      const locId = row.getCell(colId).value?.toString().trim();
      if (!locId) return;

      locations.push({
        location_id: locId,
        node_hostname: row.getCell(colHost).value?.toString().trim() || '',
        mac_addr: row.getCell(colMac).value?.toString().trim() || ''
      });
    });
  }

  return { events, songTracks, locations };
}
