export const locationsApi = {
  getLocations: async () => {
    const proj = getActiveProject();
    if (!proj) return { status: 'success', locations: [] };
    
    // If locations are missing, initialize default grid locations L1..L3, C1..C3, R1..R3
    if (!proj.locations || proj.locations.length === 0) {
      const defaults = [
        { location_id: 'L1', x_coordinate: 1, y_coordinate: 2, node_hostname: '', mac_addr: '' },
        { location_id: 'L2', x_coordinate: 1, y_coordinate: 5, node_hostname: '', mac_addr: '' },
        { location_id: 'L3', x_coordinate: 1, y_coordinate: 8, node_hostname: '', mac_addr: '' },
        { location_id: 'C1', x_coordinate: 5, y_coordinate: 2, node_hostname: '', mac_addr: '' },
        { location_id: 'C2', x_coordinate: 5, y_coordinate: 5, node_hostname: '', mac_addr: '' },
        { location_id: 'C3', x_coordinate: 5, y_coordinate: 8, node_hostname: '', mac_addr: '' },
        { location_id: 'R1', x_coordinate: 9, y_coordinate: 2, node_hostname: '', mac_addr: '' },
        { location_id: 'R2', x_coordinate: 9, y_coordinate: 5, node_hostname: '', mac_addr: '' },
        { location_id: 'R3', x_coordinate: 9, y_coordinate: 8, node_hostname: '', mac_addr: '' }
      ];
      proj.locations = defaults;
      saveActiveProject(proj);
    }
    return { status: 'success', locations: proj.locations };
  },

  updateLocation: async (locData) => {
    const proj = getActiveProject();
    if (!proj) return { status: 'error', message: 'No active project selected' };

    proj.locations = (proj.locations || []).map(loc => {
      if (loc.location_id === locData.location_id) {
        return { ...loc, ...locData };
      }
      return loc;
    });

    saveActiveProject(proj);
    return { status: 'success' };
  },

  clearLocationAssignments: async () => {
    const proj = getActiveProject();
    if (!proj) return { status: 'error', message: 'No active project selected' };

    proj.locations = (proj.locations || []).map(loc => ({
      ...loc,
      node_hostname: '',
      mac_addr: ''
    }));

    saveActiveProject(proj);
    return { status: 'success' };
  },

  importLocationAssignments: async (file) => {
    // Read and merge locations coordinates from Excel workbook upload
    try {
      const parsed = await importShowWorkbook(file);
      const proj = getActiveProject();
      if (!proj) return { status: 'error', message: 'No active project selected' };

      if (parsed.locations && parsed.locations.length > 0) {
        // Merge or replace
        proj.locations = parsed.locations;
        saveActiveProject(proj);
      }

      return { status: 'success', imported_count: parsed.locations.length };
    } catch (err) {
      return { status: 'error', message: err.message };
    }
  }
};

