// Local in-memory state for audio tracks selection and uploads in browser
let mockAudioFiles = ['oneHitWonders_2026_v0.mp3', 'oneHitWonders_2026_v2.mp3'];
let mockSelectedAudio = '';
window.audioBlobs = window.audioBlobs || {};

export const controlApi = {
  getAudioFiles: async () => {
    return { status: 'success', audio_files: mockAudioFiles };
  },
  uploadAudio: async (file) => {
    if (!mockAudioFiles.includes(file.name)) {
      mockAudioFiles = [...mockAudioFiles, file.name];
    }
    window.audioBlobs = window.audioBlobs || {};
    window.audioFiles = window.audioFiles || {};
    
    window.audioBlobs[file.name] = URL.createObjectURL(file);
    window.audioFiles[file.name] = file;
    mockSelectedAudio = file.name;
    return { status: 'success', audio_file: file.name };
  },
  selectAudioFile: async (filename) => {
    mockSelectedAudio = filename;
    return { status: 'success' };
  },
  getAudioSettings: async () => {
    return { status: 'success', output_mode: 'computer', card_name: 'Local Browser', volume: 70 };
  },
  updateAudioSettings: async (settings) => {
    return { status: 'success', ...settings };
  },
  getAudioWaveform: async (filename, peaksCount = 500) => {
    const file = window.audioFiles && window.audioFiles[filename];
    if (file) {
      try {
        const audioContext = new (window.AudioContext || window.webkitAudioContext)();
        const arrayBuffer = await file.arrayBuffer();
        const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);
        const channelData = audioBuffer.getChannelData(0);
        
        const blockSize = Math.floor(channelData.length / peaksCount);
        const peaks = [];
        for (let i = 0; i < peaksCount; i++) {
          let max = 0;
          const start = i * blockSize;
          for (let j = 0; j < blockSize; j++) {
            const val = Math.abs(channelData[start + j]);
            if (val > max) max = val;
          }
          peaks.push(max);
        }
        return { status: 'success', peaks };
      } catch (err) {
        console.error('Web Audio decoding failed, falling back to mock peaks', err);
      }
    }

    const peaks = [];
    for (let i = 0; i < peaksCount; i++) {
      const envelope = Math.sin(i * 0.05) * 0.3 + Math.cos(i * 0.15) * 0.15 + 0.45;
      const noise = Math.random() * 0.15;
      peaks.push(Math.max(0.02, Math.min(1.0, envelope + noise)));
    }
    return { status: 'success', peaks };
  },
  verifyShowScripts: async () => {
    // Script layout validation matching Pi's overlap logic
    const proj = getActiveProject();
    if (!proj) return { status: 'success', results: [] };

    const results = [];
    const eventsList = proj.events || [];
    const locationsList = proj.locations || [];

    // Check overlaps, double-wirings, or locations not present in locations sheet
    const relayWiring = {}; // { 'L1:0': [event_num] }

    eventsList.forEach(e => {
      (e.relays || []).forEach(r => {
        const key = `${r.location_id}:${r.relay_idx}`;
        if (!relayWiring[key]) relayWiring[key] = [];
        relayWiring[key].push(e.event_num);
      });
    });

    const collisions = Object.keys(relayWiring).filter(k => relayWiring[k].length > 1);
    collisions.forEach(k => {
      const parts = k.split(':');
      results.push({
        type: 'ERROR',
        message: `Relay Collision: Location ${parts[0]} Relay ${parseInt(parts[1])+1} is wired to multiple events: ${relayWiring[k].join(', ')}`
      });
    });

    // Check location existence
    eventsList.forEach(e => {
      (e.relays || []).forEach(r => {
        const exists = locationsList.some(l => l.location_id === r.location_id);
        if (!exists && r.location_id) {
          results.push({
            type: 'WARNING',
            message: `Location ${r.location_id} used in event #${e.event_num} is not registered in Locations tab`
          });
        }
      });
    });

    return { status: 'success', results };
  },
  getShowStatus: async () => {
    return { status: 'success', show_status: { state: 'idle', audio_file: mockSelectedAudio } };
  }
};

