// Internal helper for parsing CSV scripts
function parseCsvScriptFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target.result;
        const lines = text.split('\n');
        const parsedEvents = [];
        
        lines.forEach((line, idx) => {
          if (idx === 0) return; // skip header
          
          const parts = line.split(',').map(p => p.trim());
          if (parts.length >= 3) {
            const num = parts[0].replace(/"/g, '');
            const ms = parseInt(parts[1]);
            const title = parts[2].replace(/"/g, '');
            const relaysRaw = parts[3] ? parts[3].replace(/"/g, '') : '';
            
            const relays = [];
            if (relaysRaw) {
              const rParts = relaysRaw.split('&').map(r => r.trim());
              rParts.forEach(rp => {
                const sub = rp.split(':');
                if (sub.length >= 4) {
                  relays.push({
                    location_id: sub[0],
                    relay_idx: parseInt(sub[1]) || 0,
                    duration_ms: parseInt(sub[2]) || 150,
                    firework_name: sub[3]
                  });
                }
              });
            }

            if (num && !isNaN(ms)) {
              parsedEvents.push({
                event_id: num,
                event_num: num,
                timestamp_offset_ms: ms,
                title,
                fuseDelay: 0,
                setupNotes: '',
                relays
              });
            }
          }
        });
        resolve({ events: parsedEvents, songTracks: [], locations: [] });
      } catch (err) {
        reject(err);
      }
    };
    reader.readAsText(file);
  });
}
