  // Timing formatting and parsing helpers
  const formatMsToTimeString = (ms) => {
    if (ms === undefined || ms === null || isNaN(ms)) return '00:00.000';
    const mins = Math.floor(ms / 60000);
    const secs = Math.floor((ms % 60000) / 1000);
    const msecs = Math.floor(ms % 1000);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}.${msecs.toString().padStart(3, '0')}`;
  };

  const formatEventNum = (numStr) => {
    if (!numStr) return '';
    const parts = numStr.split('.');
    if (parts.length > 2) {
      const last = parts[parts.length - 1];
      const baseStr = parts.slice(0, -1).join('.');
      const baseNum = parseFloat(baseStr);
      if (!isNaN(baseNum)) {
        const rounded = Math.round(baseNum * 10000) / 10000;
        return `${rounded}.${last}`;
      }
    } else {
      const num = parseFloat(numStr);
      if (!isNaN(num)) {
        return (Math.round(num * 10000) / 10000).toString();
      }
    }
    return numStr;
  };

  const parseTimeStringToMs = (str) => {
    if (!str) return 0;
    const trimmed = str.trim();
    const parts = trimmed.split(':');
    if (parts.length === 2) {
      const mins = parseInt(parts[0], 10);
      const secondsParts = parts[1].split('.');
      const secs = parseInt(secondsParts[0], 10);
      let msecs = 0;
      if (secondsParts.length === 2) {
        msecs = parseInt(secondsParts[1].padEnd(3, '0').substring(0, 3), 10);
      }
      if (isNaN(mins) || isNaN(secs) || isNaN(msecs)) return null;
      return mins * 60000 + secs * 1000 + msecs;
    } else if (parts.length === 1) {
      const secondsParts = parts[0].split('.');
      if (secondsParts.length === 2) {
        const secs = parseInt(secondsParts[0], 10);
        const msecs = parseInt(secondsParts[1].padEnd(3, '0').substring(0, 3), 10);
        if (isNaN(secs) || isNaN(msecs)) return null;
        return secs * 1000 + msecs;
      } else {
        const num = parseInt(parts[0], 10);
        if (!isNaN(num)) return num;
      }
    }
    return null;
  };

