  const getComplianceMetrics = () => {
    const scriptLocations = new Set();
    const locationRelayUsage = {};
    
    events.forEach(evt => {
      if (evt.song) return;
      evt.relays.forEach(r => {
        if (r.location_id) {
          scriptLocations.add(r.location_id);
          if (!locationRelayUsage[r.location_id]) {
            locationRelayUsage[r.location_id] = new Set();
          }
          locationRelayUsage[r.location_id].add(r.relay_idx);
        }
      });
    });

    const locationsUsed = scriptLocations.size;
    let partialRelayNodes = 0;
    let fullRelayNodes = 0;
    let overusedRelayNodes = 0;

    Object.keys(locationRelayUsage).forEach(locId => {
      const relayCount = locationRelayUsage[locId].size;
      if (relayCount < 8) {
        partialRelayNodes++;
      } else if (relayCount === 8) {
        fullRelayNodes++;
      } else if (relayCount > 8) {
        overusedRelayNodes++;
      }
    });

    const discoveredNodes = allNodes.filter(n => isOnline(n)).length;
    const undiscoveredNodes = allNodes.filter(n => !isOnline(n)).length;

    let noRelaysCount = 0;
    let noLocationCount = 0;
    let noBoardCount = 0;

    events.forEach(evt => {
      if (evt.song) return;
      if (!evt.relays || evt.relays.length === 0) {
        noRelaysCount++;
      } else {
        let hasMissingLocation = false;
        let hasMissingBoard = false;
        evt.relays.forEach(r => {
          if (!r.location_id || r.location_id.trim() === '') {
            hasMissingLocation = true;
          } else {
            const matchedNode = nodes.find(n => n.location_id === r.location_id || n.hostname === r.location_id || n.node_id === r.location_id);
            if (!matchedNode) {
              hasMissingBoard = true;
            }
          }
        });
        if (hasMissingLocation) noLocationCount++;
        if (hasMissingBoard) noBoardCount++;
      }
    });

    return {
      locationsUsed,
      partialRelayNodes,
      fullRelayNodes,
      overusedRelayNodes,
      discoveredNodes,
      undiscoveredNodes,
      noRelaysCount,
      noLocationCount,
      noBoardCount
    };
  };

